# D. THE REFLECTION PAIRING
# ---------------------------------------------------------------------------
def realify(matrix: sp.Matrix) -> sp.Matrix:
    """[[Re Q, -Im Q], [Im Q, Re Q]] -- the realification of a complex matrix.

    det of this 2N x 2N REAL matrix equals |det Q|^2 for any complex Q.  That is
    the identity the reflection-pairing reading rests on, and it is RECOMPUTED
    here rather than cited.
    """
    n = matrix.rows
    re = sp.Matrix(n, n, lambda i, j: sp.re(matrix[i, j]))
    im = sp.Matrix(n, n, lambda i, j: sp.im(matrix[i, j]))
    out = sp.zeros(2 * n)
    for i in range(n):
        for j in range(n):
            out[i, j] = re[i, j]
            out[i, j + n] = -im[i, j]
            out[i + n, j] = im[i, j]
            out[i + n, j + n] = re[i, j]
    return out


def measure_reflection(bench: dict) -> dict:
    """THE REFLECTION-PAIRING LEGS, both recomputed.

    Leg one is the exact realified-determinant identity at the bench.  Leg two
    is the herm-surrogate chart-blindness at ONE point: the Hermitian surrogate
    law at chart column 0 against chart column 1 on the constant carrier, beside
    the squared law at the same two columns.
    """
    fixture = b174.Fixture(LX, tag="b176-reflect")
    q = fixture.q({})
    det = b174.dm_det(q)
    n2 = b174.norm2(det)
    real_det = b174.dm_det(realify(q))
    # Z(Q) Z(Q^dag) = pi^{2N} / (det Q · det Q^dag).  The pi powers cancel in
    # every ratio, so the measured object is the exact rational |det Q|^2.
    conjugate_product = sp.cancel(sp.expand(det * sp.conjugate(det)))

    const = b174.Fixture(LX, pattern=b174.constant_pattern(LX), tag="b176-cst")
    column0 = b174.readout_laws(b174.menu_states(const, b174.RECORD_LEVEL, 0))
    column1 = b174.readout_laws(b174.menu_states(const, b174.RECORD_LEVEL, 1))
    herm_blind = b174.laws_equal(column0, column1, "herm")
    squared_sensitive = not b174.laws_equal(column0, column1, "sq")
    gap, _ = b174.law_gap(column0, column1, "sq")
    return {
        "det": det,
        "det_norm2": n2,
        "realified_rows": realify(q).rows,
        "realified_det": real_det,
        "identity_defect": sp.cancel(real_det - n2),
        "identity_exact": sp.cancel(real_det - n2) == 0,
        "conjugate_product_defect": sp.cancel(conjugate_product - n2),
        "conjugate_product_exact": sp.cancel(conjugate_product - n2) == 0,
        "det_nonzero": det != 0,
        "herm_law_column0": column0["herm"]["law"],
        "herm_law_column1": column1["herm"]["law"],
        "herm_chart_blind": herm_blind,
        "squared_chart_sensitive": squared_sensitive,
        "chart_gap": gap,
        "chart_gap_nonzero": gap != 0,
        "chart_gap_bracket": bracket(gap),
        "chart_gap_bracket_agrees": bracket(gap) == CHART_GAP_BRACKET,
        # THE STATUS FLAG, declared: this block proposes and does not prove.
        "principle_is_derived": False,
    }


