def holo_call_sites() -> int:
    """LIVE CALL SITES that would assemble a holomorphic action in THIS runner.

    A Call node with keyword `action` whose constant value is one of the
    declared holomorphic action names.  Naming the strings in a module constant
    is NOT a call site, which is exactly the distinction that lets the spec be
    written down while the arm stays unrun.
    """
    tree = ast.parse(Path(__file__).read_text(encoding="utf-8"))
    total = 0
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        for keyword in node.keywords:
            if (keyword.arg == "action"
                    and isinstance(keyword.value, ast.Constant)
                    and keyword.value.value in HOLO_ACTIONS):
                total += 1
    return total


def measure_interference(deep: bool) -> dict:
    """I0 = M_joint - P_one at the two free record cells, exactly.

    P_one is the one-cell formation-conditional law at (2,0) with (3,0) LEFT
    UNPINNED -- which means that cell sits at the AMBIENT carrier value 3/5,
    itself in the menu.  M_joint is the marginal onto (2,0) of the joint law
    over the sixteen pinned pairs.  THE DIFFERENCE IS THE EXPECTED CLASSICAL
    BASELINE and this gate labels it as one.
    """
    fixture = b174.Fixture(LX, tag="b176-i0")
    one_raw = tuple(
        sp.cancel(ONE / b174.norm2(b174.dm_det(fixture.q({RECORD_CELL: a}))))
        for a in MENU)
    p_one = b174.normalize(one_raw)
    joint_raw = {}
    routes_agree = []
    for a in MENU:
        for b in MENU:
            q = fixture.q({RECORD_CELL: a, SECOND_CELL: b})
            det = b174.dm_det(q)
            if deep and a == b:
                # THE SECOND ROUTE, run only under --deep on the diagonal pins:
                # Berkowitz against DomainMatrix.  MEASURED, not asserted.
                routes_agree.append(
                    sp.expand(det - q.det(method="berkowitz")) == 0)
            joint_raw[(a, b)] = sp.cancel(ONE / b174.norm2(det))
    total = sp.cancel(sum(joint_raw.values(), Z0))
    m_joint = tuple(
        sp.cancel(sum((joint_raw[(a, b)] for b in MENU), Z0) / total)
        for a in MENU)
    i0 = tuple(sp.cancel(m - p) for m, p in zip(m_joint, p_one))
    numerators, denominator = common_denominator(i0)
    return {
        "cells": (RECORD_CELL, SECOND_CELL),
        "p_one": p_one,
        "p_one_normalized": sp.cancel(sum(p_one, Z0)) == ONE,
        "m_joint": m_joint,
        "m_joint_normalized": sp.cancel(sum(m_joint, Z0)) == ONE,
        "joint_cardinality": len(joint_raw),
        "joint_positive": all(v > 0 for v in joint_raw.values()),
        "i0": i0,
        "numerators": numerators,
        "denominator": denominator,
        "literals_agree": (numerators == I0_NUMERATORS
                           and denominator == I0_DENOMINATOR),
        "all_nonzero": all(v != 0 for v in i0),
        "signs": tuple(sp.sign(v) for v in i0),
        "signs_agree": tuple(int(sp.sign(v)) for v in i0) == I0_SIGNS,
        "sum_zero": sp.cancel(sum(i0, Z0)) == 0,
        "brackets": tuple(bracket(v) for v in i0),
        "brackets_agree": tuple(bracket(v) for v in i0) == I0_BRACKETS,
        # THE AMBIENT READING, measured: the unpinned cell's value IS in the
        # menu, which is why the baseline is classical.
        "ambient_sigma": b171.CARRIER_SIGMA,
        "ambient_in_menu": b171.CARRIER_SIGMA in MENU,
        # THE HOLOMORPHIC ARM: SPECCED AND UNRUN, and the absence is MEASURED.
        "holo_machinery_exists": all(
            f"self.Q_{name}" in inspect.getsource(b171.Site)
            for name in ("holo_t", "holo_x")),
        "holo_call_sites": holo_call_sites(),
        "holo_arm_run": HOLO_ARM_RUN,
        "deep_routes_checked": len(routes_agree),
        "deep_routes_agree": all(routes_agree) and len(routes_agree) == len(MENU),
        "deep": deep,
    }


# ---------------------------------------------------------------------------
# F. THE SESQUILINEARITY INHERITANCE at 12x6
# ---------------------------------------------------------------------------
def matrix_zero(matrix: sp.MatrixBase) -> bool:
    return all(sp.simplify(entry) == 0 for entry in matrix)


def chart_translation(t_count: int, width: int) -> sp.Matrix:
    size = t_count * width
    out = sp.zeros(size)
    for t in range(t_count):
        for x in range(width):
            out[width * t + (x + CHART_STEP) % width, width * t + x] = 1
    return out


def chart_projectors(translation: sp.Matrix) -> tuple:
    size = translation.rows
    return tuple(
        sum((OMEGA ** (-k * power) * translation ** power for power in range(3)),
            sp.zeros(size)) / 3
        for k in range(3))


def chart_character(t: int, parity: int, k: int, width: int, size: int):
    vector = sp.zeros(size, 1)
    for orbit in range(3):
        vector[width * t + parity + CHART_STEP * orbit] = (
            OMEGA ** (-k * orbit) / sp.sqrt(3))
    return vector


def measure_sesquilinearity(bench: dict) -> dict:
    """THE Z_3 CHART STRUCTURE at 12x6, the FORCED vacuity, and the exact
    sesquilinear restriction.

    The cross-sector block leg is measured HERE precisely so the note can
    disclose it as VACUOUS: P_1 P_2 = 0 identically, so P_1 W P_2 = W P_1 P_2 = 0
    for ANY W commuting with U and the test carries no information about Q.
    """
    q = bench["wide_q"]
    size = q.rows
    translation = chart_translation(COVER_T // 2, WIDE_LX)
    identity = sp.eye(size)
    projectors = chart_projectors(translation)
    commutator = sp.expand(q * translation - translation * q)
    f_one = chart_character(0, 0, 1, WIDE_LX, size)
    f_two = chart_character(0, 0, 2, WIDE_LX, size)
    x, y = sp.symbols("x y", real=True)
    phi = (x + sp.I * y) * f_one
    beta = sp.simplify((f_one.H * q * f_one)[0])
    restricted = sp.simplify((phi.H * q * phi)[0])
    return {
        "size": size,
        "translation_unitary": translation.H * translation == identity,
        "translation_order_three": translation ** 3 == identity,
        "commutes_exactly": matrix_zero(commutator),
        "projectors_hermitian": all(matrix_zero(p.H - p) for p in projectors),
        "projectors_orthogonal_idempotent": all(
            matrix_zero(projectors[k] * projectors[j]
                        - (projectors[k] if k == j else sp.zeros(size)))
            for k in range(3) for j in range(3)),
        "projectors_resolve": matrix_zero(
            sum(projectors, sp.zeros(size)) - identity),
        "projector_traces": tuple(sp.trace(p) for p in projectors),
        # THE FORCING that makes the cross-sector block test vacuous, MEASURED.
        "cross_projector_product_zero": matrix_zero(projectors[1] * projectors[2]),
        "cross_block_zero": matrix_zero(projectors[1] * q * projectors[2]),
        "cross_block_is_vacuous": bool(
            matrix_zero(projectors[1] * projectors[2])
            and matrix_zero(commutator)),
        "omega_is_primitive_cube_root": sp.expand(OMEGA ** 2 + OMEGA + 1) == 0,
        "beta": beta,
        "beta_is_pinned": beta == BETA,
        "restricted_form_defect": sp.expand(restricted - beta * (x ** 2 + y ** 2)),
        "no_antilinear_term": sp.expand(
            restricted - beta * (x ** 2 + y ** 2)) == 0,
        "f_one": f_one,
        "f_two": f_two,
        "projectors": projectors,
        "translation": translation,
        # THE ASSEMBLY GRAMMAR, inspected in the committed layer's own source.
        "grammar": measure_assembly_grammar(),
    }


