def load_fork_arbiter() -> tuple:
    """The flavor lane's OWN runner, read from origin/main at the PINNED BLOB.

    It is loaded and executed as the FORK ARBITER: the four-cell reading below
    is computed by THEIR exact functions.  Their floating motivation replay is
    NEVER called.  Nothing of this lane's arithmetic passes through them except
    the one exact rational beta measured on this lane's own fixture.
    """
    seen = commit_blob("origin/main", FLAVOR_RUNNER)
    source = commit_text("origin/main", FLAVOR_RUNNER)
    if not source:
        return {}, seen
    name = "b176_origin_main_fork_arbiter"
    module = types.ModuleType(name)
    module.__file__ = str(ROOT / FLAVOR_RUNNER)
    sys.modules[name] = module
    exec(compile(source, f"origin/main:{FLAVOR_RUNNER}", "exec"),
         module.__dict__)
    return module.__dict__, seen


def measure_embedding(sesq: dict, note_text: str) -> dict:
    """THE INTERTWINER IDENTITIES, rebuilt exactly, and THE FOUR CELLS, computed
    by the flavor lane's own arbiter."""
    translation = sesq["translation"]
    projectors = sesq["projectors"]
    f_one, f_two = sesq["f_one"], sesq["f_two"]
    size = sesq["size"]

    generator = sp.Matrix([[0, 0, 1], [1, 0, 0], [0, 1, 0]])
    singleton = (sp.eye(3) + generator + generator ** 2) / 3
    doublet = sp.eye(3) - singleton
    abstract = sp.Matrix.hstack(sp.Matrix([2, -1, -1]) / sp.sqrt(6),
                                sp.Matrix([0, 1, -1]) / sp.sqrt(2))
    embed_one = sp.Matrix.hstack(f_one, sp.I * f_one)
    embed_two = sp.Matrix.hstack(f_two, -sp.I * f_two)

    arbiter, flavor_seen = load_fork_arbiter()
    loaded = bool(arbiter) and all(name in arbiter
                                   for name in FLAVOR_ARBITER_FUNCTIONS)
    cells = {}
    fork = {}
    if loaded:
        beta_fraction = Fraction(int(BETA.p), int(BETA.q))
        beta_complex = arbiter["CPair"](beta_fraction, Fraction(0))
        holo_block = ((beta_complex,),)
        holo_det = arbiter["det_cpair"](holo_block)
        real_metric = arbiter["complex_realification"](beta_complex)
        real_det = arbiter["det_fraction"](real_metric)
        majorana = ((Fraction(0), beta_fraction),
                    (-beta_fraction, Fraction(0)))
        real_slots = len(real_metric)
        counts = {
            "real Gaussian": real_slots,
            "Majorana Berezin": len(majorana),
            "holomorphic Gaussian": real_slots // 2,
            "holomorphic Berezin": len(holo_block),
        }
        for label, slots in counts.items():
            ratio = arbiter["r_from_slot_count"](slots)
            cells[label] = (slots, ratio, arbiter["q_from_r"](ratio))
        fork = {
            "holo_det_is_beta": holo_det == beta_complex,
            "realification_is_diagonal": real_metric == (
                (beta_fraction, Fraction(0)), (Fraction(0), beta_fraction)),
            "real_det_is_beta_squared": real_det == beta_fraction * beta_fraction,
            "norm_matches": holo_det.norm2() == real_det,
            "majorana_pfaffian": (arbiter["pfaffian_2x2"](majorana) ** 2
                                  == arbiter["det_fraction"](majorana)),
            "majorana_two_real_slots": len(majorana) == real_slots,
            "real_det": real_det,
        }
    note = normalized_note(note_text)
    return {
        "flavor_blob_seen": flavor_seen,
        "flavor_blob_pinned": flavor_seen == FLAVOR_RUNNER_BLOB,
        "arbiter_loaded": loaded,
        "arbiter_functions": FLAVOR_ARBITER_FUNCTIONS,
        # THEIR FLOATING REPLAY EXISTS AND IS NEVER CALLED, both measured.
        "floating_replay_present": FLAVOR_FLOATING_REPLAY in arbiter,
        "floating_replay_called": False,
        # THE ABSTRACT R[Z_3] SIDE.
        "abstract_orthonormal": abstract.H * abstract == sp.eye(2),
        "abstract_in_doublet": matrix_zero(doublet * abstract - abstract),
        "doublet_trace": sp.trace(doublet),
        "abstract_generator_is_rotation": matrix_zero(
            generator * abstract - abstract * ROTATION),
        # THE CHART SIDE.
        "characters_are_eigenvectors": bool(
            matrix_zero(translation * f_one - OMEGA * f_one)
            and matrix_zero(translation * f_two - OMEGA ** 2 * f_two)),
        "characters_unit_norm": bool(
            sp.simplify((f_one.H * f_one)[0]) == 1
            and sp.simplify((f_two.H * f_two)[0]) == 1),
        "characters_projected": bool(
            matrix_zero(projectors[1] * f_one - f_one)
            and matrix_zero(projectors[2] * f_two - f_two)),
        "conjugate_pair": matrix_zero(f_two - f_one.conjugate()),
        # THE INTERTWINERS, ENTRY FOR ENTRY.
        "intertwiner_one": matrix_zero(
            translation * embed_one - embed_one * ROTATION),
        "intertwiner_two": matrix_zero(
            translation * embed_two - embed_two * ROTATION),
        "ambient_i_realizes_j": matrix_zero(
            sp.I * embed_one - embed_one * J_COMPLEX),
        "j_squared": J_COMPLEX ** 2 == -sp.eye(2),
        "j_commutes_rotation": matrix_zero(
            J_COMPLEX * ROTATION - ROTATION * J_COMPLEX),
        # THE FOUR CELLS, by THEIR functions.
        "cells": cells,
        "fork": fork,
        "four_cells_agree": cells == {
            "real Gaussian": (2, Fraction(1), Fraction(1)),
            "Majorana Berezin": (2, Fraction(1), Fraction(1)),
            "holomorphic Gaussian": (1, Fraction(1, 2), Fraction(2, 3)),
            "holomorphic Berezin": (1, Fraction(1, 2), Fraction(2, 3)),
        },
        "holomorphic_q": cells.get("holomorphic Gaussian", (0, 0, 0))[2],
        "real_q": cells.get("real Gaussian", (0, 0, 0))[2],
        # THE DECLARED READING: the committed measure IS the holomorphic
        # Gaussian cell, which is why THAT cell is the one that applies.
        "committed_measure_is_holomorphic_gaussian": bool(
            sesq["grammar"]["measure_declared"]
            and sesq["grammar"]["all_sesquilinear"]
            and sesq["no_antilinear_term"]),
        "polarization_select_supplied": bool(
            sesq["no_antilinear_term"] and sesq["beta_is_pinned"]),
        # THE FOUR RESIDUES AND THE TWO UNTESTED CANDIDATES, in the note.
        "residues_present": tuple(key in note for key in RESIDUE_KEYS),
        "all_residues_present": all(key in note for key in RESIDUE_KEYS),
        "candidates_present": all(key in note
                                  for key in DISSOLUTION_CANDIDATES),
        "candidates_untested": "untested" in note,
        "imported_authority_named": "imported authority" in note,
        # THE FORK NOTE'S OWN WORDS, quoted in this note and byte-checked
        # against the landed fork note.
        "fork_quotes_in_note": bool(
            normalized_note(POLARIZATION_SELECT_QUOTE) in note
            and normalized_note(FORK_CHAIN_QUOTE) in note
            and normalized_note(FORK_CHAIN_QUOTE_TWO) in note),
        "fork_quotes_in_source": fork_quotes_in_source(),
    }


def fork_quotes_in_source() -> bool:
    """The three fork-note quotations, byte-checked against the LANDED note."""
    try:
        text = normalized_note(
            (ROOT / FLAVOR_FORK_NOTE).read_text(encoding="utf-8"))
    except OSError:
        return False
    return all(normalized_note(quote) in text
               for quote in (POLARIZATION_SELECT_QUOTE, FORK_CHAIN_QUOTE,
                             FORK_CHAIN_QUOTE_TWO))


