def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "bar_items_registered": False,
        "flavor_note_adopted": False,
        "axioms_withhold_site": True,
        "readout_principle_derived": False,
        "herm_surrogate_chart_blind": True,
        "holo_arm_run": False,
        "interference_nonzero": True,
        "cross_block_vacuous": True,
        "antilinear_term_present": False,
        "polarization_select_supplied": True,
        "firing_cell": "holomorphic",
        "residues_required": RESIDUE_SCOPE_KEYS,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_proposal_registered":
        # THE BAR DENIED: the two proposals asserted registered, which zero
        # registered and zero adopted objects forbid.
        claims["bar_items_registered"] = True
    elif mutation == "claim_flavor_note_adopted":
        # THE DISCIPLINE DENIED: the flavor lane's note asserted ADOPTED rather
        # than quoted, which zero adopted objects forbid.
        claims["flavor_note_adopted"] = True
    elif mutation == "claim_axioms_supply_formation_site":
        # THE ROLE SPLIT DENIED AT ITS SOURCE: the axioms asserted to supply the
        # formation site and rate, which reading note (2)'s own words forbid.
        claims["axioms_withhold_site"] = False
    elif mutation == "claim_readout_derived":
        # THE STATUS OVERCLAIMED: the reflection-pairing principle asserted
        # DERIVED rather than a candidate, which this block does not establish.
        claims["readout_principle_derived"] = True
    elif mutation == "claim_herm_surrogate_chart_sensitive":
        # THE MEASURED BLINDNESS DENIED: the Hermitian surrogate asserted
        # chart-sensitive, which the exact equality of its two column laws
        # forbids.
        claims["herm_surrogate_chart_blind"] = False
    elif mutation == "claim_interference_run":
        # THE UNRUN ARM ASSERTED RUN: the holomorphic arm claimed measured, which
        # zero holomorphic call sites forbid.
        claims["holo_arm_run"] = True
    elif mutation == "claim_interference_zero":
        # THE BASELINE DENIED: I0 asserted zero, which four exact nonzero
        # rationals forbid.
        claims["interference_nonzero"] = False
    elif mutation == "drop_vacuity_disclosure":
        # THE VACUITY DENIED: the cross-sector block test asserted to carry
        # content, which P_1 P_2 = 0 and [Q,U] = 0 forbid.
        claims["cross_block_vacuous"] = False
    elif mutation == "claim_antilinear_term_present":
        # THE SESQUILINEARITY DENIED: an antilinear z^2 term asserted induced,
        # which the exact restriction (3193/2240)|z|^2 forbids.
        claims["antilinear_term_present"] = True
    elif mutation == "claim_polarization_select_underived":
        # THE FIRING DENIED: POLARIZATION-SELECT asserted NOT supplied by this
        # embedding, which the exact sesquilinear restriction and the pinned beta
        # forbid.
        claims["polarization_select_supplied"] = False
    elif mutation == "claim_q_one":
        # THE WRONG CELL ASSERTED: the REAL cell claimed to fire at Q = 1, which
        # the committed complex Gaussian measure and the arbiter's own four-cell
        # table forbid.
        claims["firing_cell"] = "real"
    elif mutation == "drop_residues":
        # THE RESIDUES DROPPED from the required set, which gate G forbids -- all
        # four are required, not a subset.
        claims["residues_required"] = ()
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim")
    return claims


