@dataclass(frozen=True)
class Facts:
    deep: bool
    main_head: str
    authority: AuthorityCertificate
    note_at_final_path: bool
    scope: dict
    banners: dict
    role: dict
    reflection: dict
    interference: dict
    sesq: dict
    embedding: dict
    exact_no_float: bool
    source_files: int
    source_floats: int
    source_forbidden: int


def evaluate_gates(facts: Facts, claims: dict, elapsed_ns: int) -> dict:
    authority = facts.authority
    parent_blobs_ok = (authority.parent_artifact_blobs
                       if claims["parent_pin"] == "resolved"
                       else authority.stale_parent_artifact_blobs)
    gate_a = bool(
        AUDIT_INPUT_PATHS == (
            "docs/ADMISSIBILITY_DIRAC_KAHLER_COMPLEX_STRUCTURE_SYNTHESIS_BOUNDED_THEOREM_NOTE_2026-08-23.md",
            "docs/MINIMAL_AXIOMS_2026-06-29.md",
            "docs/audit/data/axiom_premise_nodes.json",
            "docs/ADMISSIBILITY_DIRAC_KAHLER_PINCER_IDENTITY_CROSS_LANE_BOUNDED_THEOREM_NOTE_2026-08-22.md",
            "scripts/admissibility_dirac_kahler_pincer_identity_cross_lane_2026_08_22.py",
            "docs/KOIDE_BEREZIN_DETC_VS_DETR_FORK_MECHANISM_NOTE_2026-06-04.md",
        )
        and PARENT_ARTIFACTS == (BLOCK175_NOTE, BLOCK175_RUNNER)
        and len(PARENT_ARTIFACT_BLOBS) == len(PARENT_ARTIFACTS) == 2
        and facts.main_head == claims["main_head"]
        and authority.fixed_authority
        and authority.parent_import_landed
        and authority.parent_pin_is_commit
        and authority.parent_ref_and_ancestry
        and parent_blobs_ok
        # THE STALE PIN: a REAL ancestor of HEAD that carries NEITHER Block 175
        # artifact, which is exactly what makes the stale mutation bite.
        and authority.stale_is_real_ancestor
        and authority.stale_carries_neither_artifact
        # THE FLAVOR-RUNNER BLOB PIN, verified at origin/main before gate G ever
        # executes that source.
        and authority.flavor_blob_pinned
        and FLAVOR_RUNNER not in AUDIT_INPUT_PATHS)

    ban = facts.banners
    conv = ban["convention"]
    bench = ban["bench"]
    gate_b = bool(
        # THE CONVENTION COLLISION, MEASURED on identical matrices.
        conv["pairs"] == EXPECTED_CONVENTION
        and conv["landed_psd"] and conv["here_psd"] and conv["orders_differ"]
        and conv["instrument_agree"][0] == conv["instrument_agree"][1]
        # THE IMPOSED-OBJECT BANNER and THE TWO PROPOSALS, as measured objects.
        and ban["imposed_objects"] == 8
        and ban["registered_objects"] == 0
        and ban["adopted_objects"] == 0
        and ban["proposed_to_owner"] == 2
        and ban["owner_decisions"] == 1
        and ban["axiom_clause_is_verbatim"]
        and (ban["registered_objects"] == 0 and ban["adopted_objects"] == 0)
        == (not claims["bar_items_registered"])
        and (ban["adopted_objects"] == 0 and ban["flavor_note_is_quoted"])
        == (not claims["flavor_note_adopted"])
        # THE 12x4 BENCH ANCHOR, read through the landed instrument.
        and bench["q_symbol_free"] and bench["field_matches_landed"]
        and bench["inverse_residual_zero"] and bench["congruence_zero"]
        and bench["hermq_inertia"] == EXPECTED_HERMQ_12x4
        and bench["det_routes_agree"] and bench["det_nonzero"]
        and bench["menu_is_sigma_classes"] and bench["menu_matches_parent"]
        and bench["tstar_is_five"] and bench["N"] == 24
        # AND THE 12x6 CONSTANT-CARRIER ANCHOR this block adds.
        and bench["wide_T_phys"] == 6 and bench["wide_N"] == 36
        and bench["wide_lx"] == WIDE_LX
        and bench["wide_q_symbol_free"] and bench["wide_volume_constant"]
        and bench["wide_inertia"] == EXPECTED_HERMQ_12x6
        and facts.exact_no_float
        and facts.source_floats == 0 and facts.source_forbidden == 0
        and facts.source_files >= 2)

    role = facts.role
    gate_c = bool(
        # QUOTATION INTEGRITY, both directions: in the axioms file and in this
        # block's note.
        role["all_in_axioms"] and role["all_in_note"]
        and len(role["quotations"]) == 3
        and role["reading_notes_are_interpretive"]
        and role["reading_note_supplies_value"]
        and role["open_gates_withholds_site"]
        # THE STRUCTURE, stated in the note.
        and role["note_states_role_split"]
        and role["note_states_not_rivals"]
        and role["note_states_gate_not_gap"]
        and role["note_states_negative_by_design"]
        # THE CLAIM-BOUND LEG, measured from the quotation's own words.
        and role["reading_note_withholds_site"] == claims["axioms_withhold_site"]
        and facts.scope["reading_note_two_quoted"]
        and facts.scope["open_gates_quoted"])

    ref = facts.reflection
    gate_d = bool(
        # THE REALIFIED-DETERMINANT IDENTITY, exact.
        ref["det_nonzero"]
        and ref["realified_rows"] == 48
        and ref["identity_exact"]
        and ref["identity_defect"] == 0
        and ref["conjugate_product_exact"]
        # THE HERM SURROGATE, MEASURED chart-blind against a chart-sensitive
        # squared law at an exactly nonzero gap.
        and ref["squared_chart_sensitive"]
        and ref["chart_gap_nonzero"]
        and ref["chart_gap_bracket_agrees"]
        and ref["herm_chart_blind"] == claims["herm_surrogate_chart_blind"]
        # THE STATUS: A CANDIDATE, NEVER A DERIVATION.
        and ref["principle_is_derived"] == claims["readout_principle_derived"]
        and facts.scope["candidate_not_derivation"]
        and facts.scope["scalar_sector_successor"]
        and facts.exact_no_float)

    inter = facts.interference
    gate_e = bool(
        inter["cells"] == (RECORD_CELL, SECOND_CELL)
        and inter["joint_cardinality"] == 16
        and inter["joint_positive"]
        and inter["p_one_normalized"] and inter["m_joint_normalized"]
        # THE FOUR EXACT DELTAS against the embedded literals.
        and inter["literals_agree"]
        and inter["signs_agree"]
        and inter["brackets_agree"]
        and inter["sum_zero"]
        # THE CLASSICAL READING, measured: the unpinned value IS in the menu.
        and inter["ambient_in_menu"]
        and facts.scope["classical_baseline"]
        and facts.scope["unpinned_is_ambient"]
        # THE HOLOMORPHIC ARM: the machinery EXISTS and is NEVER CALLED.
        and inter["holo_machinery_exists"]
        and inter["holo_call_sites"] == 0
        and facts.scope["holo_arm_specced_unrun"]
        and facts.scope["prediction_registered"]
        # THE TWO CLAIM-BOUND LEGS.
        and inter["all_nonzero"] == claims["interference_nonzero"]
        and (inter["holo_arm_run"] or inter["holo_call_sites"] > 0)
        == claims["holo_arm_run"]
        and ((inter["deep_routes_agree"]) if facts.deep else True)
        and facts.exact_no_float)

    sesq = facts.sesq
    grammar = sesq["grammar"]
    gate_f = bool(
        sesq["size"] == 36
        and sesq["translation_unitary"] and sesq["translation_order_three"]
        and sesq["commutes_exactly"]
        and sesq["omega_is_primitive_cube_root"]
        and sesq["projectors_hermitian"]
        and sesq["projectors_orthogonal_idempotent"]
        and sesq["projectors_resolve"]
        and sesq["projector_traces"] == EXPECTED_PROJECTOR_TRACES
        # THE EXACT RESTRICTION.
        and sesq["beta_is_pinned"]
        and sesq["restricted_form_defect"] == 0
        # THE ASSEMBLY GRAMMAR: sesquilinear-only, measured in the source.
        and grammar["measure_declared"] and grammar["operator_assembled"]
        and grammar["phi_line_count"] == 3 and grammar["all_sesquilinear"]
        and grammar["no_antilinear_block"]
        # THE VACUITY, measured AND disclosed.
        and sesq["cross_projector_product_zero"]
        and sesq["cross_block_zero"]
        and facts.scope["vacuity_disclosed"]
        and facts.scope["vacuity_forced"]
        # THE TWO CLAIM-BOUND LEGS.
        and sesq["cross_block_is_vacuous"] == claims["cross_block_vacuous"]
        and (not sesq["no_antilinear_term"])
        == claims["antilinear_term_present"]
        and facts.exact_no_float)

    emb = facts.embedding
    firing_q = (emb["holomorphic_q"] if claims["firing_cell"] == "holomorphic"
                else emb["real_q"])
    gate_g = bool(
        # THE ARBITER, at its pinned blob, with only its exact functions used.
        emb["flavor_blob_pinned"] and emb["arbiter_loaded"]
        and emb["floating_replay_present"]
        and not emb["floating_replay_called"]
        # THE ABSTRACT R[Z_3] SIDE and THE CHART SIDE.
        and emb["abstract_orthonormal"] and emb["abstract_in_doublet"]
        and emb["doublet_trace"] == 2
        and emb["abstract_generator_is_rotation"]
        and emb["characters_are_eigenvectors"] and emb["characters_unit_norm"]
        and emb["characters_projected"] and emb["conjugate_pair"]
        # THE INTERTWINERS, ENTRY FOR ENTRY.
        and emb["intertwiner_one"] and emb["intertwiner_two"]
        and emb["ambient_i_realizes_j"] and emb["j_squared"]
        and emb["j_commutes_rotation"]
        # THE FOUR CELLS, by THEIR functions, and the committed cell.
        and emb["cells"] == EXPECTED_FOUR_CELLS
        and emb["four_cells_agree"]
        and emb["fork"]["holo_det_is_beta"]
        and emb["fork"]["realification_is_diagonal"]
        and emb["fork"]["real_det_is_beta_squared"]
        and emb["fork"]["norm_matches"]
        and emb["fork"]["majorana_pfaffian"]
        and emb["fork"]["majorana_two_real_slots"]
        and emb["committed_measure_is_holomorphic_gaussian"]
        and facts.scope["holomorphic_gaussian_cell"]
        # THE QUOTATIONS, in this note and in the landed fork note.
        and emb["fork_quotes_in_note"] and emb["fork_quotes_in_source"]
        # THE FOUR RESIDUES AND THE TWO UNTESTED CANDIDATES.
        and emb["all_residues_present"] and emb["candidates_present"]
        and emb["candidates_untested"] and emb["imported_authority_named"]
        and tuple(claims["residues_required"]) == RESIDUE_SCOPE_KEYS
        and all(facts.scope[key] for key in claims["residues_required"])
        # THE TWO CLAIM-BOUND LEGS: the SUPPLY, and WHICH CELL FIRES.
        and emb["polarization_select_supplied"]
        == claims["polarization_select_supplied"]
        and firing_q == Fraction(2, 3)
        and facts.exact_no_float)

    required = tuple(claims["required_scope_keys"])
    budget = DEEP_RUNTIME_BUDGET_SEC if facts.deep else RUNTIME_BUDGET_SEC
    gate_h = bool(
        # THE NOTE AT ITS FINAL PATH.  An unlanded draft fails HERE and only
        # here; the scope certificate is still computed from the declared draft
        # fallback so the supervisor can see every key before landing.
        facts.note_at_final_path
        and NOTE_PATH.name == FINAL_NOTE_NAME
        and set(facts.scope) == set(SCOPE_KEYS)
        # THE FULL KEY SET IS REQUIRED, not a subset.  That is what gives the
        # drop mutation its teeth once the note is landed.
        and required == SCOPE_KEYS
        and all(facts.scope[key] for key in required)
        and len(MUTATIONS) == 15
        and len(set(MUTATIONS)) == 15
        and set(MUTATION_GATE) == set(MUTATIONS)
        and set(MUTATION_GATE.values()) == set("ABCDEFGH")
        # THE N5 FENCE: N5-prefixed, 9 to 12 lines, the standard sections.
        and N5_FENCE.startswith("N5: ")
        and 9 <= N5_FENCE.count("\n") + 1 <= 12
        and all(N5_FENCE.count(f"\n{name}:") == 1
                for name in ("per_site", "per_mode", "per_block",
                             "lattice_wide", "per_scope", "RESULT",
                             "DECISION_CUT", "TOE"))
        and POOL_TWO_LEADS == 4
        and HANDOFF_ITEMS == 3
        and elapsed_ns <= budget * 1_000_000_000)

    return {"A": gate_a, "B": gate_b, "C": gate_c, "D": gate_d,
            "E": gate_e, "F": gate_f, "G": gate_g, "H": gate_h}


